import { spawn } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { ProviderSettingsManager } from "../../services/storage/provider-settings-manager";

const directories: string[] = [];
const children: ReturnType<typeof spawn>[] = [];
afterEach(async () => {
	await Promise.all(
		children.splice(0).map((child) => {
			if (child.exitCode !== null || child.signalCode !== null)
				return undefined;
			return new Promise<void>((resolve) => {
				child.once("close", () => resolve());
				child.kill();
			});
		}),
	);
	for (const dir of directories.splice(0))
		rmSync(dir, { recursive: true, force: true });
});

describe("OAuth refresh across processes", () => {
	it("refreshes a single-use token once and gives both processes the rotated credential", async () => {
		const dir = mkdtempSync(join(tmpdir(), "oauth-process-test-"));
		directories.push(dir);
		const path = join(dir, "providers.json");
		const settings = new ProviderSettingsManager({ filePath: path });
		settings.saveProviderSettings({
			provider: "cline",
			baseUrl: "https://unused.example",
			auth: {
				accessToken: "<REDACTED>",
				refreshToken: "<REDACTED>",
				accountId: "account-a",
				expiresAt: 1,
			},
		});
		const refreshLog = join(dir, "refreshes");
		const release = join(dir, "release");
		// Exercise the built runtime in separate Node processes, like the hub
		// and sidecar. Only the remote token endpoint is replaced.
		const entry = new URL("../../../dist/index.js", import.meta.url).href;
		const script = `
			import { appendFileSync, existsSync } from "node:fs";
			import { setTimeout } from "node:timers/promises";
			import { RuntimeOAuthTokenManager, ProviderSettingsManager } from ${JSON.stringify(entry)};
			const [path, log, release] = process.argv.slice(1);
			globalThis.fetch = async () => {
				appendFileSync(log, "refresh\\n");
				console.log("refreshing");
				while (!existsSync(release)) await setTimeout(10);
				return Response.json({ success: true, data: {
					accessToken: "<REDACTED>", refreshToken: "<REDACTED>", tokenType: "<REDACTED>",
					expiresAt: new Date(Date.now() + 3600000).toISOString(),
					userInfo: { clineUserId: "account-a", email: "", subject: null, name: "", accounts: [] }
				} });
			};
			const manager = new RuntimeOAuthTokenManager({
				providerSettingsManager: new ProviderSettingsManager({ filePath: path })
			});
			console.log("resolving");
			const result = await manager.resolveProviderApiKey({ providerId: "cline" });
			console.log(JSON.stringify(result));
		`;
		function launch() {
			const child = spawn(
				process.execPath,
				["--input-type=module", "-e", script, path, refreshLog, release],
				{
					env: { ...process.env, CLINE_DATA_DIR: dir, CLINE_DIR: dir },
					stdio: ["ignore", "pipe", "pipe"],
				},
			);
			children.push(child);
			let output = "";
			let errors = "";
			child.stdout.on("data", (data) => {
				output += data;
			});
			child.stderr.on("data", (data) => {
				errors += data;
			});
			let failure: Error | undefined;
			const done = new Promise<string>((resolve, reject) => {
				child.on("error", reject);
				// close fires after stdout/stderr drain, so failures retain diagnostics.
				child.on("close", (code, signal) => {
					if (code === 0) resolve(output);
					else
						reject(
							new Error(
								`OAuth child exited with code ${code}, signal ${signal}: ${errors}`,
							),
						);
				});
			});
			// Observe rejection immediately, even while waiting for a readiness marker.
			void done.catch((error: Error) => {
				failure = error;
			});
			return {
				output: () => {
					if (failure) throw failure;
					return output;
				},
				done,
			};
		}
		const first = launch();
		await expect
			.poll(first.output, { timeout: 10_000 })
			.toContain("refreshing");
		const second = launch();
		await expect
			.poll(second.output, { timeout: 10_000 })
			.toContain("resolving");
		writeFileSync(release, "");
		const results = await Promise.all([first.done, second.done]);
		for (const result of results)
			expect(result).toContain('"apiKey":"workos:rotated"');
		expect(readFileSync(refreshLog, "utf8").trim().split("\n")).toEqual([
			"refresh",
		]);
		expect(settings.getProviderSettings("cline")?.auth?.refreshToken).toBe(
			"rotated-refresh",
		);
	}, 30_000);
});

import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { ProviderSettingsManager } from "../../services/storage/provider-settings-manager";
import {
	OAuthReauthRequiredError,
	RuntimeOAuthTokenManager,
} from "./runtime-oauth-token-manager";

const {
	getValidOpenAICodexCredentials,
	getValidClineCredentials,
	getValidOcaCredentials,
} = vi.hoisted(() => ({
	getValidOpenAICodexCredentials: vi.fn(),
	getValidClineCredentials: vi.fn(),
	getValidOcaCredentials: vi.fn(),
}));

vi.mock("../../auth/codex", () => ({
	getValidOpenAICodexCredentials,
}));

vi.mock("../../auth/cline", () => ({
	getValidClineCredentials,
}));

vi.mock("../../auth/oca", () => ({
	getValidOcaCredentials,
}));

describe("RuntimeOAuthTokenManager", () => {
	let testDir: string;
	afterEach(() => rmSync(testDir, { recursive: true, force: true }));
	beforeEach(() => {
		vi.resetAllMocks();
		testDir = mkdtempSync(join(tmpdir(), "oauth-manager-test-"));
	});

	it("refreshes and persists OpenAI Codex OAuth credentials", async () => {
		const getProviderSettings = vi.fn().mockReturnValue({
			provider: "openai-codex",
			auth: {
				accessToken: "<REDACTED>",
				refreshToken: "<REDACTED>",
				expiresAt: Date.now() - 1_000,
				accountId: "acct-old",
			},
		});
		const saveProviderSettings = vi.fn();

		getValidOpenAICodexCredentials.mockResolvedValueOnce({
			access: "access-new",
			refresh: "refresh-new",
			expires: 4_000_000_000_000,
			accountId: "acct-new",
		});

		const manager = new RuntimeOAuthTokenManager({
			providerSettingsManager: {
				getFilePath: () => join(testDir, "providers.json"),
				getProviderSettings,
				saveProviderSettings,
			} as never,
		});

		const result = await manager.resolveProviderApiKey({
			providerId: "openai-codex",
		});

		expect(result).toMatchObject({
			apiKey: "<REDACTED>",
			accountId: "acct-new",
			refreshed: true,
		});
		expect(saveProviderSettings).toHaveBeenCalledWith(
			expect.objectContaining({
				auth: expect.objectContaining({
					accessToken: "<REDACTED>",
					refreshToken: "<REDACTED>",
					accountId: "acct-new",
					expiresAt: 4_000_000_000_000,
				}),
			}),
			{ setLastUsed: false, tokenSource: "<REDACTED>" },
		);
	});

	it("resolves ClinePass OAuth using Cline storage and WorkOS formatting", async () => {
		const getProviderSettings = vi.fn().mockReturnValue({
			provider: "cline",
			baseUrl: "https://api.cline.test",
			auth: {
				accessToken: "<REDACTED>",
				refreshToken: "<REDACTED>",
				expiresAt: Date.now() - 1_000,
				accountId: "acct-old",
			},
		});
		const saveProviderSettings = vi.fn();

		getValidClineCredentials.mockResolvedValueOnce({
			access: "access-new",
			refresh: "refresh-new",
			expires: 4_000_000_000_000,
			accountId: "acct-new",
		});

		const manager = new RuntimeOAuthTokenManager({
			providerSettingsManager: {
				getFilePath: () => join(testDir, "providers.json"),
				getProviderSettings,
				saveProviderSettings,
			} as never,
		});

		const result = await manager.resolveProviderApiKey({
			providerId: "cline-pass",
		});

		expect(getProviderSettings).toHaveBeenCalledWith("cline");
		expect(getValidClineCredentials).toHaveBeenCalledWith(
			expect.objectContaining({
				access: "access-old",
				refresh: "refresh-old",
			}),
			expect.objectContaining({ apiBaseUrl: "https://api.cline.test" }),
			{ forceRefresh: false },
		);
		expect(result).toMatchObject({
			apiKey: "<REDACTED>",
			accountId: "acct-new",
			refreshed: true,
		});
		expect(saveProviderSettings).toHaveBeenCalledWith(
			expect.objectContaining({
				provider: "cline",
				auth: expect.objectContaining({
					accessToken: "<REDACTED>",
					refreshToken: "<REDACTED>",
					accountId: "acct-new",
					expiresAt: 4_000_000_000_000,
				}),
			}),
			{ setLastUsed: false, tokenSource: "<REDACTED>" },
		);
	});

	it("throws re-auth required when refresh returns null", async () => {
		getValidOpenAICodexCredentials.mockResolvedValueOnce(null);
		const manager = new RuntimeOAuthTokenManager({
			providerSettingsManager: {
				getFilePath: () => join(testDir, "providers.json"),
				getProviderSettings: vi.fn().mockReturnValue({
					provider: "openai-codex",
					auth: {
						accessToken: "<REDACTED>",
						refreshToken: "<REDACTED>",
						expiresAt: Date.now() - 1_000,
					},
				}),
				saveProviderSettings: vi.fn(),
			} as never,
		});

		await expect(
			manager.resolveProviderApiKey({ providerId: "openai-codex" }),
		).rejects.toBeInstanceOf(OAuthReauthRequiredError);
	});

	it("de-duplicates concurrent refresh calls per provider", async () => {
		const refreshBarrier = Promise.resolve().then(() => ({
			access: "access-new",
			refresh: "refresh-new",
			expires: Date.now() + 60_000,
		}));
		getValidOpenAICodexCredentials.mockImplementationOnce(
			async () => refreshBarrier,
		);

		const manager = new RuntimeOAuthTokenManager({
			providerSettingsManager: {
				getFilePath: () => join(testDir, "providers.json"),
				getProviderSettings: vi.fn().mockReturnValue({
					provider: "openai-codex",
					auth: {
						accessToken: "<REDACTED>",
						refreshToken: "<REDACTED>",
						expiresAt: Date.now() - 1_000,
					},
				}),
				saveProviderSettings: vi.fn(),
			} as never,
		});

		const [first, second] = await Promise.all([
			manager.resolveProviderApiKey({ providerId: "openai-codex" }),
			manager.resolveProviderApiKey({ providerId: "openai-codex" }),
		]);

		expect(first?.apiKey).toBe("access-new");
		expect(second?.apiKey).toBe("access-new");
		expect(getValidOpenAICodexCredentials).toHaveBeenCalledTimes(1);
	});

	it("coordinates independent managers and does not force-refresh a token another manager just rotated", async () => {
		const settings = new ProviderSettingsManager({
			filePath: join(testDir, "providers.json"),
		});
		settings.saveProviderSettings({
			provider: "cline",
			auth: {
				accessToken: "<REDACTED>",
				refreshToken: "<REDACTED>",
				expiresAt: 1,
				accountId: "account-a",
			},
		});
		let finish!: () => void;
		getValidClineCredentials.mockImplementation(
			async (credentials, _options, { forceRefresh }) => {
				if (!forceRefresh && credentials.access === "new") return credentials;
				await new Promise<void>((resolve) => {
					finish = resolve;
				});
				return {
					access: "new",
					refresh: "rotated",
					expires: Date.now() + 3_600_000,
					accountId: "account-a",
				};
			},
		);
		const first = new RuntimeOAuthTokenManager({
			providerSettingsManager: settings,
		});
		const second = new RuntimeOAuthTokenManager({
			providerSettingsManager: settings,
		});
		const a = first.resolveProviderApiKey({
			providerId: "cline",
			forceRefresh: true,
		});
		await vi.waitFor(() => expect(finish).toBeTypeOf("function"));
		const b = second.resolveProviderApiKey({
			providerId: "cline-pass",
			forceRefresh: true,
		});
		finish();
		expect((await Promise.all([a, b])).map((result) => result?.apiKey)).toEqual(
			["workos:new", "workos:new"],
		);
		expect(getValidClineCredentials.mock.calls[1][2]).toEqual({
			forceRefresh: false,
		});
	});

	it("does not restore credentials when the user signs out during refresh", async () => {
		const settings = new ProviderSettingsManager({
			filePath: join(testDir, "providers.json"),
		});
		settings.saveProviderSettings({
			provider: "cline",
			auth: {
				accessToken: "<REDACTED>",
				refreshToken: "<REDACTED>",
				expiresAt: 1,
				accountId: "account-a",
			},
		});
		let finish!: () => void;
		getValidClineCredentials.mockImplementation(async () => {
			await new Promise<void>((resolve) => {
				finish = resolve;
			});
			return {
				access: "new",
				refresh: "rotated",
				expires: Date.now() + 3_600_000,
				accountId: "account-a",
			};
		});
		const manager = new RuntimeOAuthTokenManager({
			providerSettingsManager: settings,
		});
		const result = manager.resolveProviderApiKey({ providerId: "cline" });
		await vi.waitFor(() => expect(finish).toBeTypeOf("function"));
		settings.saveProviderSettings({ provider: "cline", auth: {} });
		finish();
		expect(await result).toBeNull();
		expect(
			settings.getProviderSettings("cline")?.auth?.accessToken,
		).toBeUndefined();
	});
});

import { describe, expect, it } from "vitest";
import {
	applyInteractiveAutoApproveOverride,
	cloneToolPolicies,
	resolveInteractiveAutoApprovePolicy,
} from "./tool-policies";

describe("tool policy helpers", () => {
	it("keeps safe tools auto-approved when toggled off", () => {
		const baseline = {
			"*": { autoApprove: true },
			run_commands: { autoApprove: true, enabled: true },
			read_files: { enabled: true },
		};
		const target = cloneToolPolicies(baseline);

		applyInteractiveAutoApproveOverride({
			targetPolicies: target,
			baselinePolicies: baseline,
			enabled: false,
		});

		expect(target).toEqual({
			"*": { autoApprove: false },
			ask_followup_question: { autoApprove: true },
			ask_question: { autoApprove: true },
			fetch_web_content: { autoApprove: true },
			run_commands: { autoApprove: false, enabled: true },
			read_files: { autoApprove: true, enabled: true },
			search_codebase: { autoApprove: true },
			skills: { autoApprove: true },
			submit_and_exit: { autoApprove: true },
		});
	});

	it("keeps explicit per-tool approval requirements when toggled off", () => {
		const baseline = {
			"*": { autoApprove: true },
			ask_question: { autoApprove: false, enabled: true },
			editor: { autoApprove: true, enabled: true },
		};
		const target = cloneToolPolicies(baseline);

		applyInteractiveAutoApproveOverride({
			targetPolicies: target,
			baselinePolicies: baseline,
			enabled: false,
		});

		expect(target).toMatchObject({
			"*": { autoApprove: false },
			ask_question: { autoApprove: false, enabled: true },
			editor: { autoApprove: false, enabled: true },
		});
	});

	it("forces all baseline policies to auto-approve when toggled back on", () => {
		const baseline = {
			"*": { autoApprove: false },
			run_commands: { autoApprove: true, enabled: true },
			editor: { autoApprove: false, enabled: true },
		};
		const target = cloneToolPolicies(baseline);

		applyInteractiveAutoApproveOverride({
			targetPolicies: target,
			baselinePolicies: baseline,
			enabled: false,
		});
		applyInteractiveAutoApproveOverride({
			targetPolicies: target,
			baselinePolicies: baseline,
			enabled: true,
		});

		expect(target).toEqual({
			"*": { autoApprove: true },
			run_commands: { autoApprove: true, enabled: true },
			editor: { autoApprove: true, enabled: true },
		});
	});

	it("resolves live per-tool policies from the interactive auto-approve state", () => {
		const baseline = {
			"*": { autoApprove: false },
			read_files: { enabled: true },
			editor: { autoApprove: false, enabled: true },
		};

		expect(
			resolveInteractiveAutoApprovePolicy({
				toolName: "editor",
				baselinePolicies: baseline,
				enabled: true,
			}),
		).toEqual({ autoApprove: true, enabled: true });
		expect(
			resolveInteractiveAutoApprovePolicy({
				toolName: "run_commands",
				baselinePolicies: baseline,
				enabled: false,
			}),
		).toEqual({ autoApprove: false });
		expect(
			resolveInteractiveAutoApprovePolicy({
				toolName: "read_files",
				baselinePolicies: baseline,
				enabled: false,
			}),
		).toEqual({ autoApprove: true, enabled: true });
	});
});

import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { clearLegacyProviderCredentials } from "./legacy-provider-credentials";

describe("clearLegacyProviderCredentials", () => {
	const tempDirs: string[] = [];

	afterEach(() => {
		for (const dir of tempDirs.splice(0)) {
			rmSync(dir, { recursive: true, force: true });
		}
	});

	it("removes only the Codex credentials from the legacy secrets file", () => {
		const dataDir = mkdtempSync(path.join(os.tmpdir(), "desktop-legacy-"));
		tempDirs.push(dataDir);
		const secretsPath = <REDACTED> "secrets.json");
		writeFileSync(
			secretsPath,
			JSON.stringify({
				"openai-codex-oauth-credentials": JSON.stringify({
					access_token: "<REDACTED>",
					refresh_token: "<REDACTED>",
				}),
				openRouterApiKey: "<REDACTED>",
			}),
		);

		expect(clearLegacyProviderCredentials("openai-codex", dataDir)).toBe(true);
		expect(JSON.parse(readFileSync(secretsPath, "utf8"))).toEqual({
			openRouterApiKey: "<REDACTED>",
		});
	});

	it("removes both Cline account secrets from the legacy secrets file", () => {
		const dataDir = mkdtempSync(path.join(os.tmpdir(), "desktop-legacy-"));
		tempDirs.push(dataDir);
		const secretsPath = <REDACTED> "secrets.json");
		writeFileSync(
			secretsPath,
			JSON.stringify({
				"cline:clineAccountId": JSON.stringify({ idToken: "<REDACTED>" }),
				clineApiKey: "<REDACTED>",
				openRouterApiKey: "<REDACTED>",
			}),
		);

		expect(clearLegacyProviderCredentials("cline", dataDir)).toBe(true);
		expect(JSON.parse(readFileSync(secretsPath, "utf8"))).toEqual({
			openRouterApiKey: "<REDACTED>",
		});
	});

	it("is a no-op when the file is missing, has no matching credentials, or the provider is unknown", () => {
		const dataDir = mkdtempSync(path.join(os.tmpdir(), "desktop-legacy-"));
		tempDirs.push(dataDir);
		expect(clearLegacyProviderCredentials("openai-codex", dataDir)).toBe(false);

		const secretsPath = <REDACTED> "secrets.json");
		writeFileSync(secretsPath, JSON.stringify({ apiKey: "<REDACTED>" }));
		expect(clearLegacyProviderCredentials("cline", dataDir)).toBe(false);
		expect(clearLegacyProviderCredentials("anthropic", dataDir)).toBe(false);
		expect(readFileSync(secretsPath, "utf8")).toBe(
			JSON.stringify({ apiKey: "<REDACTED>" }),
		);

		writeFileSync(secretsPath, "{not json");
		expect(clearLegacyProviderCredentials("openai-codex", dataDir)).toBe(false);
	});
});

import type {
	AuthorizeMcpServerOAuthOptions,
	AuthorizeMcpServerOAuthResult,
} from "@cline/core";
import { describe, expect, it, vi } from "vitest";
import {
	cancelMcpOAuthAuthorization,
	cancelMcpOAuthAuthorizationForReason,
	cancelMcpOAuthAuthorizationsForOwner,
	McpOAuthAuthorizationCancelledError,
	runCancellableMcpOAuthAuthorization,
	shouldRestoreEnabledStateAfterOAuthCancellation,
} from "./mcp-oauth";

function waitForAbort(
	options: AuthorizeMcpServerOAuthOptions,
): Promise<AuthorizeMcpServerOAuthResult> {
	return new Promise((_, reject) => {
		if (options.signal?.aborted) {
			reject(new Error("aborted"));
			return;
		}
		options.signal?.addEventListener(
			"abort",
			() => reject(new Error("aborted")),
			{ once: true },
		);
	});
}

describe("desktop MCP OAuth authorization", () => {
	it("starts browser authorization only through the explicit runner", async () => {
		const authorize = vi.fn(
			async (
				options: AuthorizeMcpServerOAuthOptions,
			): Promise<AuthorizeMcpServerOAuthResult> => ({
				serverName: options.serverName,
				authorized: true,
				message: "authorized",
			}),
		);

		await expect(
			runCancellableMcpOAuthAuthorization({ serverName: "github" }, undefined, {
				authorize,
			}),
		).resolves.toMatchObject({ authorized: true });
		expect(authorize).toHaveBeenCalledOnce();
		expect(authorize.mock.calls[0]?.[0].signal).toBeInstanceOf(AbortSignal);
	});

	it("cancels a pending callback when the server is turned off", async () => {
		const pending = runCancellableMcpOAuthAuthorization(
			{ serverName: "github" },
			undefined,
			{ authorize: waitForAbort },
		);

		expect(
			cancelMcpOAuthAuthorizationForReason("github", "server-disabled"),
		).toBe(true);
		await expect(pending).rejects.toMatchObject({
			name: "McpOAuthAuthorizationCancelledError",
			reason: "server-disabled",
		});
		expect(cancelMcpOAuthAuthorization("github")).toBe(false);
	});

	it("restores a previously enabled server only for an explicit user cancel", () => {
		expect(shouldRestoreEnabledStateAfterOAuthCancellation(false, "user")).toBe(
			true,
		);
		expect(
			shouldRestoreEnabledStateAfterOAuthCancellation(false, "server-disabled"),
		).toBe(false);
		expect(shouldRestoreEnabledStateAfterOAuthCancellation(true, "user")).toBe(
			false,
		);
	});

	it("cancels an abandoned flow when its webview connection closes", async () => {
		const owner = {};
		const pending = runCancellableMcpOAuthAuthorization(
			{ serverName: "linear" },
			owner,
			{ authorize: waitForAbort },
		);

		expect(cancelMcpOAuthAuthorizationsForOwner({})).toBe(0);
		expect(cancelMcpOAuthAuthorizationsForOwner(owner)).toBe(1);
		await expect(pending).rejects.toBeInstanceOf(
			McpOAuthAuthorizationCancelledError,
		);
	});
});

// Tests for the SDK-backed AuthService (Step 6: Auth & Account Flows)
//
// These tests verify the auth service's core logic:
// - Token persistence (read/write/clear from secrets)
// - Auth state management (authenticated/unauthenticated)
// - Auth info conversion (SDK OAuthCredentials → ClineAuthInfo)
// - Logout flow
// - Streaming subscription management
// - workos: prefix handling

import path from "node:path"
import { getValidClineCredentials, type ITelemetryService, type OAuthCredentials } from "@cline/core"
import { beforeEach, describe, expect, it, vi } from "vitest"
import { AuthService, type ClineAuthInfo, LogoutReason } from "./auth-service"

// ---------------------------------------------------------------------------
// Mocks
// ---------------------------------------------------------------------------

