// Plugin
// ---------------------------------------------------------------------------

const plugin: AgentPlugin = {
	name: "portable-subagents",
	manifest: { capabilities: ["tools"] },

	setup(api, ctx) {
		const logger = ctx.logger;
		logger?.log("portable-subagents plugin setup", {
			sessionId: ctx.session?.sessionId,
			defaultPreset: DEFAULT_AGENT_PRESET,
			backendMode: DEFAULT_BACKEND_MODE,
			workspaceRoot: ctx.workspaceInfo?.rootPath,
		});
		// See the telemetry.ts example for the full ctx.telemetry contract.
		pluginTelemetry = ctx.telemetry;
		pluginTelemetry?.capture({
			event: "subagents_setup",
			properties: {
				default_preset: DEFAULT_AGENT_PRESET,
				backend_mode: DEFAULT_BACKEND_MODE,
			},
		});

		// -- start_subagent: Start a new subagent session --
		api.registerTool(
			toRegisteredTool(
				createTool({
					name: "start_subagent",
					description: `Start a background subagent run and return its session ID immediately. Prefer a preset from list_agent_presets; when omitted, this tool uses the bundled "${DEFAULT_AGENT_PRESET}" preset automatically. Use get_subagent to poll, or keep notifyParent enabled to have the result pushed back into the parent session.`,
					inputSchema: StartSubagentInput,
					timeoutMs: 60_000,
					retryable: false,
					async execute(input, ctx) {
						const mgr = await getSessionManager();
						const baseCwd = envOr("CLINE_SUBAGENT_CWD", process.cwd());
						const defs = readAgentDefinitions(baseCwd);
						const presetName = input.preset ?? DEFAULT_AGENT_PRESET;
						const def = defs.find((d) => d.name === presetName);
						if (presetName && !def && !input.instructions?.trim()) {
							throw new Error(`Unknown agent preset: ${presetName}`);
						}

						const cwd = resolve(
							baseCwd,
							input.workingDirectory ?? def?.cwd ?? ".",
						);
						const providerId =
							input.providerId ?? def?.providerId ?? DEFAULT_PROVIDER_ID;
						const modelId = input.modelId ?? def?.modelId ?? DEFAULT_MODEL_ID;
						const prompt = [
							def?.systemPrompt?.trim(),
							input.instructions?.trim(),
						]
							.filter(Boolean)
							.join("\n\n");
						if (!prompt) {
							throw new Error(
								`Subagent "${input.label}" needs instructions. Provide "instructions" or use an available preset such as "${DEFAULT_AGENT_PRESET}".`,
							);
						}

						const { sessionId } = await mgr.start({
							config: {
								providerId,
								modelId,
								cwd,
								workspaceRoot: cwd,
								enableTools: true,
								enableSpawnAgent: false,
								enableAgentTeams: false,
								pluginPaths: [],
								systemPrompt: prompt,
								maxIterations: input.maxIterations ?? def?.maxIterations,
							},
							interactive: false,
						});

						const subagent: RunningSubagent = {
							sessionId,
							parentSessionId: parentSessionId(ctx),
							name: input.label,
							task: input.task,
							agent: input.preset,
							startedAt: Date.now(),
							status: "running",
						};
						subagents.set(sessionId, subagent);
						logger?.log("Started subagent", {
							sessionId,
							toolName: "start_subagent",
							label: input.label,
							preset: def?.name ?? input.preset,
							providerId,
							modelId,
						});
						pluginTelemetry?.recordCounter("subagents.started", 1, {
							preset: def?.name ?? input.preset ?? "custom",
							provider_id: providerId,
						});
						void runSubagentTurn(
							subagent,
							input.task,
							input.notifyParent !== false,
						);

						return {
							status: "started",
							sessionId,
							label: subagent.name,
							preset: def?.name ?? input.preset,
							task: subagent.task,
						};
					},
				}),
			),
		);

		// -- list_agent_presets: Show available agent definitions --
		api.registerTool(
			toRegisteredTool(
				createTool({
					name: "list_agent_presets",
					description:
						"List the available subagent presets, including bundled, global, and project-level definitions.",
					inputSchema: z.object({}).strict(),
					async execute(_input, _ctx) {
						const baseCwd = envOr("CLINE_SUBAGENT_CWD", process.cwd());
						const agents = readAgentDefinitions(baseCwd).map((a) => ({
							name: a.name,
							description: a.description,
							providerId: a.providerId ?? DEFAULT_PROVIDER_ID,
							modelId: a.modelId ?? DEFAULT_MODEL_ID,
							source: a.source,
						}));
						return {
							agents,
							text: agents.length
								? agents
										.map(
											(a) =>
												`- ${a.name} [${a.source}] (${a.providerId}/${a.modelId})${a.description ? `: ${a.description}` : ""}`,
										)
										.join("\n")
								: "No agent definitions found.",
						};
					},
				}),
			),
		);

		// -- message_subagent: Send follow-up to an existing session --
		api.registerTool(
			toRegisteredTool(
				createTool({
					name: "message_subagent",
					description:
						"Send a follow-up message to an existing subagent session and return immediately.",
					inputSchema: MessageSubagentInput,
					timeoutMs: 60_000,
					retryable: false,
					async execute(input, ctx) {
						const mgr = await getSessionManager();
						const record = await mgr.get(input.sessionId);
						if (!record) {
							throw new Error(`Unknown session: ${input.sessionId}`);
						}

						const subagent: RunningSubagent = subagents.get(
							input.sessionId,
						) ?? {
							sessionId: input.sessionId,
							parentSessionId: parentSessionId(ctx),
							name: input.sessionId,
							task: input.prompt,
							startedAt: Date.now(),
							status: "running",
						};
						subagent.parentSessionId = parentSessionId(ctx);
						subagent.task = input.prompt;
						subagent.status = "running";
						subagent.error = undefined;
						subagents.set(subagent.sessionId, subagent);

						logger?.log("Queued subagent follow-up", {
							sessionId: subagent.sessionId,
							toolName: "message_subagent",
							label: subagent.name,
						});
						void runSubagentTurn(
							subagent,
							input.prompt,
							input.notifyParent !== false,
						);
						return {
							status: "started",
							sessionId: subagent.sessionId,
							label: subagent.name,
							task: subagent.task,
						};
					},
				}),
			),
		);

		// -- get_subagent: Check subagent result --
		api.registerTool(
			toRegisteredTool(
				createTool({
					name: "get_subagent",
					description:
						"Get the latest status, output, and error details for a subagent session.",
					inputSchema: GetSubagentInput,
					async execute(input, _ctx) {
						const subagent = subagents.get(input.sessionId);
						if (!subagent) {
							return {
								status: "unknown",
								sessionId: input.sessionId,
								text: `No tracked session: ${input.sessionId}`,
							};
						}
						return {
							status: subagent.status,
							sessionId: subagent.sessionId,
							label: subagent.name,
							task: subagent.task,
							finishReason: subagent.finishReason,
							error: subagent.error,
							text:
								subagent.resultText ??
								(subagent.status === "running" ? "Still running." : ""),
						};
					},
				}),
			),
		);

		// -- save_handoff: Persist a conversation-scoped handoff file --
		api.registerTool(
			toRegisteredTool(
				createTool({
					name: "save_handoff",
					description:
						"Save text into the conversation handoff store so other agents in this conversation can read it later.",
					inputSchema: SaveHandoffInput,
					async execute(input, ctx) {
						const filePath = resolveHandoffPath(ctx, input.path);
						mkdirSync(dirname(filePath), { recursive: true });
						writeFileSync(filePath, input.content, "utf8");
						return { path: filePath, handoffPath: input.path };
					},
				}),
			),
		);

		// -- read_handoff: Read a conversation-scoped handoff file --
		api.registerTool(
			toRegisteredTool(
				createTool({
					name: "read_handoff",
					description: "Read text from the conversation handoff store.",
					inputSchema: ReadHandoffInput,
					async execute(input, ctx) {
						const filePath = resolveHandoffPath(ctx, input.path);
						if (!existsSync(filePath)) {
							throw new Error(`Handoff not found: ${input.path}`);
						}
						return {
							path: filePath,
							handoffPath: input.path,
							content: readFileSync(filePath, "utf8"),
						};
					},
				}),
			),
		);

		// -- list_skills: Show available skill definitions --
		api.registerTool(
			toRegisteredTool(
				createTool({
					name: "list_skills",
					description:
						"List the available skill definitions from bundled, global, and project-level directories.",
					inputSchema: z.object({}).strict(),
					async execute(_input, _ctx) {
						const baseCwd = envOr("CLINE_SUBAGENT_CWD", process.cwd());
						const skills = readSkillDefinitions(baseCwd);
						return {
							skills: skills.map((s) => ({
								name: s.name,
								description: s.description,
								source: s.source,
							})),
							text: skills.length
								? skills
										.map(
											(s) =>
												`- ${s.name} [${s.source}]${s.description ? `: ${s.description}` : ""}`,
										)
										.join("\n")
								: "No skill definitions found.",
						};
					},
				}),
			),
		);

		// -- get_skill: Load a skill's instructions --
		api.registerTool(
			toRegisteredTool(
				createTool({
					name: "get_skill",
					description:
						"Get a skill by name, including the instructions that should be followed for that specialization.",
					inputSchema: GetSkillInput,
					async execute(input, _ctx) {
						const baseCwd = envOr("CLINE_SUBAGENT_CWD", process.cwd());
						const skills = readSkillDefinitions(baseCwd);
						const skill = skills.find((s) => s.name === input.name);
						if (!skill) {
							const available = skills.map((s) => s.name).join(", ");
							throw new Error(
								`Unknown skill: "${input.name}". Available: ${available || "none"}`,
							);
						}
						return {
							name: skill.name,
							description: skill.description,
							source: skill.source,
							instructions: skill.content,
						};
					},
				}),
			),
		);
	},
};

export { plugin };
export default plugin;

import type {
	AgentMessage,
	AgentModel,
	AgentModelEvent,
	AgentModelRequest,
	AgentRuntimeEvent,
} from "@cline/shared";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { AgentRuntime, AgentRuntimeAbortError } from "./agent-runtime";
import { Agent, createAgent } from "./index";

const { createAgentModel, createGateway } = vi.hoisted(() => {
	const createAgentModel = vi.fn();
	const createGateway = vi.fn(() => ({
		createAgentModel,
	}));
	return { createAgentModel, createGateway };
});

vi.mock("@cline/llms", () => ({
	createGateway,
}));

class ScriptedModel implements AgentModel {
	constructor(
		private readonly steps: Array<
			(
				request: AgentModelRequest,
			) => Iterable<AgentModelEvent> | AsyncIterable<AgentModelEvent>
		>,
	) {}

	async stream(
		request: AgentModelRequest,
	): Promise<AsyncIterable<AgentModelEvent>> {
		const step = this.steps.shift();
		if (!step) {
			throw new Error("No scripted model step available");
		}
		return toAsyncIterable(step(request));
	}
}

async function* toAsyncIterable(
	events: Iterable<AgentModelEvent> | AsyncIterable<AgentModelEvent>,
): AsyncIterable<AgentModelEvent> {
	for await (const event of events) {
		yield event;
	}
}

describe("AgentRuntime (provider-form config + Agent alias)", () => {
	beforeEach(() => {
		createGateway.mockClear();
		createAgentModel.mockReset();
	});

	it("constructs the runtime via the llms gateway in ESM-safe code", () => {
		const model = new ScriptedModel([]);
		createAgentModel.mockReturnValue(model);

		const agent = new Agent({
			providerId: "openai",
			modelId: "gpt-5",
			apiKey: "<REDACTED>",
		});

		expect(agent).toBeInstanceOf(Agent);
		expect(createGateway).toHaveBeenCalledWith({
			providerConfigs: [
				{
					providerId: "openai",
					apiKey: "<REDACTED>",
					baseUrl: undefined,
					headers: undefined,
					options: undefined,
				},
			],
		});
		expect(createAgentModel).toHaveBeenCalledWith({
			providerId: "openai",
			modelId: "gpt-5",
		});
	});

	it("passes provider options through to the llms gateway", () => {
		const model = new ScriptedModel([]);
		createAgentModel.mockReturnValue(model);

		new Agent({
			providerId: "openai-compatible",
			modelId: "gpt-4.1",
			apiKey: "<REDACTED>",
			baseUrl: "https://example.openai.azure.com/openai/deployments/gpt-4.1",
			options: { apiVersion: "2025-01-01-preview" },
		});

		expect(createGateway).toHaveBeenCalledWith({
			providerConfigs: [
				{
					providerId: "openai-compatible",
					apiKey: "<REDACTED>",
					baseUrl:
						"https://example.openai.azure.com/openai/deployments/gpt-4.1",
					headers: undefined,
					options: { apiVersion: "2025-01-01-preview" },
				},
			],
		});
	});

	it("forwards abort() to the active AgentRuntime", async () => {
		let abortReason: unknown;
		const model = new ScriptedModel([
			async function* (request) {
				yield { type: "text-delta", text: "partial" };
				await new Promise<void>((resolve) => {
					request.signal?.addEventListener(
						"abort",
						() => {
							abortReason = request.signal?.reason;
							resolve();
						},
						{ once: true },
					);
				});
				yield { type: "finish", reason: "aborted" };
			},
		]);
		createAgentModel.mockReturnValue(model);

		const agent = new Agent({
			providerId: "openai",
			modelId: "gpt-5",
		});

		const runPromise = agent.run("cancel me");
		for (let i = 0; i < 20; i += 1) {
			if (agent.snapshot().status === "running") {
				break;
			}
			await new Promise((resolve) => setTimeout(resolve, 0));
		}
		agent.abort("user cancelled");

		await expect(runPromise).resolves.toMatchObject({
			status: "aborted",
		});
		expect(abortReason).toBeInstanceOf(AgentRuntimeAbortError);
		if (!(abortReason instanceof AgentRuntimeAbortError)) {
			throw new Error("expected agent runtime abort reason");
		}
		expect(abortReason.message).toBe("user cancelled");
		expect(abortReason.reason).toBe("user cancelled");
	});

	it("createAgent() and new Agent() both return an AgentRuntime instance", () => {
		const model = new ScriptedModel([]);
		createAgentModel.mockReturnValue(model);

		const agent = createAgent({
			providerId: "anthropic",
			modelId: "claude-sonnet-4-6",
		});

		// After the facade/runtime merge (Option B), `Agent` is an alias for
		// `AgentRuntime`. Both constructors return the same class — verified
		// here so future refactors don't silently reintroduce a split.
		expect(agent).toBeInstanceOf(Agent);
		expect(agent).toBeInstanceOf(AgentRuntime);
		expect(Agent).toBe(AgentRuntime);
	});

	it("restores conversation state by rebuilding the runtime", () => {
		const model = new ScriptedModel([]);
		createAgentModel.mockReturnValue(model);

		const agent = new Agent({
			providerId: "openai",
			modelId: "gpt-5",
		});
		const messages: AgentMessage[] = [
			{
				id: "msg_1",
				role: "user",
				content: [{ type: "text", text: "hello" }],
				createdAt: 1,
			},
		];

		agent.restore(messages);

		expect(agent.snapshot().messages).toEqual(messages);
		expect(agent.snapshot().status).toBe("idle");
	});

	it("rebinds existing subscribers when restore() replaces the runtime", async () => {
		const model = new ScriptedModel([
			() => [
				{ type: "text-delta", text: "hello" },
				{ type: "finish", reason: "stop" },
			],
			() => [
				{ type: "text-delta", text: "again" },
				{ type: "finish", reason: "stop" },
			],
		]);
		createAgentModel.mockReturnValue(model);

		const agent = new Agent({
			providerId: "openai",
			modelId: "gpt-5",
		});
		const received: AgentRuntimeEvent["type"][] = [];
		const unsubscribe = agent.subscribe((event) => {
			received.push(event.type);
		});

		agent.restore([
			{
				id: "msg_1",
				role: "user",
				content: [{ type: "text", text: "restored" }],
				createdAt: 1,
			},
		]);
		await agent.run("hello");

		expect(received).toContain("run-started");
		expect(received).toContain("run-finished");

		const countAfterRun = received.length;
		unsubscribe();
		await agent.run("again");
		expect(received).toHaveLength(countAfterRun);
	});

	it("derives messageModelInfo from providerId/modelId so assistant messages carry model tags", async () => {
		const model = new ScriptedModel([
			() => [
				{ type: "text-delta", text: "hi" },
				{ type: "finish", reason: "stop" },
			],
		]);
		createAgentModel.mockReturnValue(model);

		const agent = new Agent({
			providerId: "anthropic",
			modelId: "claude-sonnet-4-6",
		});

		const result = await agent.run("hello");

		const assistant = result.messages.find((m) => m.role === "assistant");
		expect(assistant?.modelInfo).toEqual({
			id: "claude-sonnet-4-6",
			provider: "anthropic",
		});
	});

	it("prefers an explicit messageModelInfo over the derived provider/model", async () => {
		const model = new ScriptedModel([
			() => [
				{ type: "text-delta", text: "hi" },
				{ type: "finish", reason: "stop" },
			],
		]);
		createAgentModel.mockReturnValue(model);

		const agent = new Agent({
			providerId: "anthropic",
			modelId: "claude-sonnet-4-6",
			messageModelInfo: {
				id: "explicit-model",
				provider: "explicit-provider",
				family: "explicit-family",
			},
		});

		const result = await agent.run("hello");

		const assistant = result.messages.find((m) => m.role === "assistant");
		expect(assistant?.modelInfo).toEqual({
			id: "explicit-model",
			provider: "explicit-provider",
			family: "explicit-family",
		});
	});
});

